import re

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_RE = re.compile(
    r'P(?:(\d+(?:\.\d+)?)W)?(?:(\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(\d+(?:\.\d+)?)H)?(?:(\d+(?:\.\d+)?)M)?(?:(\d+(?:\.\d+)?)S)?)?'
)

_CLOCK_RE = re.compile(r'(\d+):(\d+)(?::(\d+))?')

_COMPONENTS_RE = re.compile(r'(?:\d+(?:\.\d+)?[a-zA-Z]+)+')
_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration text must not be None")

    text = text.strip()
    if not text:
        raise ValueError("duration text must not be empty")

    # Bare non-negative integer, meaning seconds.
    if re.fullmatch(r'\d+', text):
        return int(text)

    # ISO 8601 duration.
    iso_match = _ISO_RE.fullmatch(text)
    if iso_match:
        w, d, h, m, s = iso_match.groups()
        if all(g is None for g in (w, d, h, m, s)):
            raise ValueError(f"invalid duration: {text!r}")
        total = 0.0
        if w:
            total += float(w) * _UNITS['w']
        if d:
            total += float(d) * _UNITS['d']
        if h:
            total += float(h) * _UNITS['h']
        if m:
            total += float(m) * _UNITS['m']
        if s:
            total += float(s) * _UNITS['s']
        return round(total)

    # Clock notation hh:mm:ss or mm:ss.
    clock_match = _CLOCK_RE.fullmatch(text)
    if clock_match:
        parts = [int(p) for p in clock_match.groups() if p is not None]
        if len(parts) == 3:
            h, m, s = parts
        else:
            h = 0
            m, s = parts
        return h * 3600 + m * 60 + s

    # One or more number+unit components, optionally separated by spaces.
    compact = text.replace(' ', '')
    if not _COMPONENTS_RE.fullmatch(compact):
        raise ValueError(f"invalid duration: {text!r}")

    total = 0.0
    for num, unit in _COMPONENT_RE.findall(compact):
        unit_l = unit.lower()
        if unit_l not in _UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        total += float(num) * _UNITS[unit_l]

    return round(total)

